{"explanation":"Scaling a triangle by k multiplies every length—including its base and perpendicular height—by k. Since its area is A = ½bh, the new area is ½(kb)(kh) = k²A. For example, doubling the triangle makes its area four times as large; use the slider to explore other scale factors.","manimCode":"const title = new Text({ text: 'Two lengths scale — so area scales twice', fontSize: 30, color: WHITE });
title.moveTo([0, 3.25, 0]);
const formula = new MathTex({ latex: 'A_{\\mathrm{new}}=\\frac12(kb)(kh)=k^2\\,A', color: YELLOW });
await formula.waitForRender();
formula.moveTo([0, 2.45, 0]);

const baseY = -1.3;
const b = 1.8;
const h = 1.5;
const originalVertices = [[-4.8, baseY, 0], [-3, baseY, 0], [-4.2, baseY + h, 0]];
const original = new Polygon({ vertices: originalVertices, color: BLUE });
original.setFill(BLUE, 0.35);
original.setStrokeWidth(3);
const originalHeight = new Line({ start: [-4.2, baseY, 0], end: [-4.2, baseY + h, 0], color: TEAL });
const originalCaption = new Text({ text: 'Original', fontSize: 24, color: BLUE });
originalCaption.moveTo([-3.9, 0.75, 0]);
const originalBaseLabel = new MathTex({ latex: 'b', color: BLUE });
const originalHeightLabel = new MathTex({ latex: 'h', color: TEAL });
await originalBaseLabel.waitForRender();
await originalHeightLabel.waitForRender();
originalBaseLabel.moveTo([-3.9, -1.7, 0]);
originalHeightLabel.moveTo([-4.55, -0.55, 0]);

let k = 2;
function scaledVertices() {
  return [[0.2, baseY, 0], [0.2 + b * k, baseY, 0], [0.2 + 0.6 * k, baseY + h * k, 0]];
}
const enlarged = new Polygon({ vertices: scaledVertices(), color: YELLOW });
enlarged.setFill(YELLOW, 0.3);
enlarged.setStrokeWidth(3);
const enlargedHeight = new Polygon({ vertices: [[1.4, baseY, 0], [1.4, baseY + h * k, 0]], color: TEAL });
enlargedHeight.setFillOpacity(0);
enlargedHeight.setStrokeWidth(3);
const scaledBaseLabel = new MathTex({ latex: 'kb', color: YELLOW });
const scaledHeightLabel = new MathTex({ latex: 'kh', color: TEAL });
await scaledBaseLabel.waitForRender();
await scaledHeightLabel.waitForRender();
const originalAreaLabel = new MathTex({ latex: 'A=\\frac12 bh', color: BLUE });
await originalAreaLabel.waitForRender();
originalAreaLabel.moveTo([-3.9, -2.25, 0]);
let readout;
function refresh() {
  enlarged.setVertices(scaledVertices());
  const footX = 0.2 + 0.6 * k;
  enlargedHeight.setVertices([[footX, baseY, 0], [footX, baseY + h * k, 0]]);
  scaledBaseLabel.moveTo([0.2 + b * k / 2, -1.7, 0]);
  scaledHeightLabel.moveTo([footX - 0.35, baseY + h * k / 2, 0]);
  if (readout) scene.remove(readout);
  readout = new Text({ text: 'Lengths: ×' + k.toFixed(2) + '     Area: ×' + (k * k).toFixed(2), fontSize: 25, color: YELLOW });
  readout.moveTo([-1.2, -3.05, 0]);
  scene.add(readout);
}
scene.add(title, original, originalHeight, originalCaption, originalBaseLabel, originalHeightLabel, enlarged, enlargedHeight, scaledBaseLabel, scaledHeightLabel, originalAreaLabel);
refresh();
await scene.play(new Write(formula));
makeHoverable(original, scene, { hoverScale: 1, hoverOpacity: 0.65 });
makeHoverable(enlarged, scene, { hoverScale: 1, hoverOpacity: 0.65 });
const controls = new Controls(scene, { position: 'bottom-right', width: 230 });
controls.addSlider({ label: 'Scale factor k', min: 0.5, max: 2, value: k, step: 0.05, onChange: (value) => { k = value; refresh(); } });
await scene.wait(999999);"}

